package com.vibecode.roadmap.application; import com.vibecode.output.domain.TaskEvidence; import com.vibecode.roadmap.domain.RoadmapPhaseRecord; import com.vibecode.task.domain.WorkflowTask; import com.vibecode.task.domain.WorkflowTaskStatus; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class ProjectStateService {private final WorkflowService flow; public ProjectStateService(WorkflowService f){flow=f;} public ProjectState state(UUID p){List<WorkflowTask> all=flow.tasks(p);List<RoadmapPhaseRecord> phases=flow.phases(p);WorkflowTask current=all.stream().filter(t->t.status()!=WorkflowTaskStatus.COMPLETED&&t.status()!=WorkflowTaskStatus.SKIPPED).findFirst().orElse(null);RoadmapPhaseRecord phase=current==null?phases.stream().filter(x->x.status()!=com.vibecode.roadmap.domain.PhaseStatus.COMPLETED).findFirst().orElse(null):phases.stream().filter(x->x.id().equals(current.phaseId())).findFirst().orElse(null);long done=all.stream().filter(t->t.status()==WorkflowTaskStatus.COMPLETED).count();long blocked=all.stream().filter(t->t.status()==WorkflowTaskStatus.BLOCKED).count();TaskEvidence ev=current==null?null:flow.evidence(p,current.id()).stream().findFirst().orElse(null);return new ProjectState(p,phase,current,done,all.size(),blocked,all.isEmpty()?0:(int)(done*100/all.size()),all.stream().filter(t->t.status()==WorkflowTaskStatus.READY).toList(),ev);}}
